import json
from pathlib import Path

sources = json.loads(Path('source.json').read_text())
drafts = {}

def add(number, xml, reason, notes):
    if number in drafts:
        raise ValueError(number)
    drafts[number] = dict(proposed_xml=xml, reason=reason, review_notes=notes, status='rewrite_draft')

add('L121-31',
'''<p>Les propriétés privées riveraines du domaine public maritime supportent, sur une bande de trois mètres de largeur, une servitude destinée exclusivement au passage des piétons.</p>''',
'''Réécriture à droit constant : les propriétés soumises à la servitude, sa largeur et sa destination exclusive sont énoncées directement. Aucune réforme de fond n'est appliquée à cette protection du littoral.''',
'''Largeur de trois mètres et destination exclusivement piétonne conservées. Les renvois à cet article dans les articles L. 121-33, L. 121-35 et L. 121-37 restent opérants.''')

add('L121-32',
'''<p>L'autorité administrative compétente de l'État peut prendre les mesures suivantes par une décision motivée. Cette décision est prise après avis de la ou des communes intéressées et au vu du résultat d'une enquête publique réalisée conformément au chapitre IV du titre III du livre Ier du code des relations entre le public et l'administration, sous réserve des dispositions particulières du présent code :</p>
<p>1° Modifier le tracé ou les caractéristiques de la servitude pour assurer, en tenant notamment compte des obstacles de toute nature, la continuité du cheminement des piétons ou leur libre accès au rivage de la mer, ainsi que pour tenir compte des chemins ou des règles locales préexistants. Le tracé modifié peut, à titre exceptionnel, grever des propriétés non riveraines du domaine public maritime ;</p>
<p>2° Suspendre la servitude, à titre exceptionnel.</p>''',
'''Réécriture à droit constant : la procédure préalable est présentée dans deux phrases, puis les pouvoirs de modification et de suspension sont distingués dans les subdivisions existantes. Les deux finalités de la modification et son extension exceptionnelle à des propriétés non riveraines sont conservées ; aucune réforme de fond.''',
'''Les 1° et 2° et leurs positions sont maintenus. Motivation, avis communal, résultat de l'enquête publique, renvoi au code des relations entre le public et l'administration et réserve des règles particulières du code sont conservés. La suspension demeure exceptionnelle.''')

add('L121-33',
'''<p>La servitude instituée aux articles L. 121-31 et L. 121-32 ne peut grever les terrains situés à moins de quinze mètres des bâtiments à usage d'habitation édifiés avant le 1er janvier 1976, ni les terrains attenants à des maisons d'habitation et clos de murs au 1er janvier 1976. Cette interdiction ne s'applique pas lorsque l'institution de la servitude est le seul moyen d'assurer la continuité du cheminement des piétons ou leur libre accès au rivage de la mer.<br>Un décret en Conseil d'État détermine les cas dans lesquels la distance de quinze mètres peut être réduite à titre exceptionnel.</p>''',
'''Réécriture à droit constant : l'interdiction est énoncée avant son exception, dans le même alinéa. L'habilitation réglementaire reste dans l'alinéa suivant. Aucune réforme de fond.''',
'''Les deux catégories de terrains protégés restent distinctes. Seuil de quinze mètres, deux références au 1er janvier 1976, condition du seul moyen d'assurer le passage ou l'accès, caractère exceptionnel de la réduction et renvois aux articles L. 121-31 et L. 121-32 conservés.''')

add('L121-34',
'''<p>L'autorité administrative compétente de l'État peut instituer une servitude de passage des piétons transversale au rivage sur les voies et chemins privés d'usage collectif existants, sauf ceux réservés à un usage professionnel. Elle statue par une décision motivée, après avis de la ou des communes intéressées et au vu du résultat d'une enquête publique réalisée conformément au chapitre IV du titre III du livre Ier du code des relations entre le public et l'administration, sous réserve des dispositions particulières du présent code.</p>
<p>Cette servitude a pour objet de relier la voirie publique au rivage de la mer ou aux sentiers d'accès immédiat à celui-ci. Elle ne peut être instituée qu'en l'absence de voie publique située à moins de cinq cents mètres et permettant l'accès au rivage.</p>''',
'''Réécriture à droit constant : le pouvoir d'instituer la servitude est séparé de sa procédure, puis l'objet de la liaison est distingué de la condition d'absence d'accès public. Aucune réforme de fond.''',
'''Deux alinéas conservés. L'exclusion de l'usage professionnel, le seuil de cinq cents mètres et le caractère cumulatif de la proximité de la voie publique et de sa capacité à donner accès au rivage sont maintenus. La graphie « cinq cent » de la source est régularisée en « cinq cents », sans changement de valeur. Articulation avec l'extension territoriale de L. 121-51 conservée.''')

add('L121-35',
'''<p>Le propriétaire n'a droit à une indemnité au titre des servitudes instituées aux articles L. 121-31 et L. 121-34 que si ces servitudes lui causent un dommage direct, matériel et certain.</p>''',
'''Réécriture à droit constant : le titulaire du droit à indemnité et les conditions cumulatives du dommage sont exprimés directement. Aucune réforme de fond.''',
'''Les trois caractères du dommage, le lien avec les servitudes et les deux renvois sont conservés. Le texte ne crée aucune indemnisation automatique ; modalités de fixation maintenues à L. 121-36.''')

add('L121-36',
'''<p>Les parties peuvent convenir à l'amiable du montant de l'indemnité. En cas de désaccord, l'indemnité est fixée dans les conditions prévues au deuxième alinéa de l'article L. 105-1.<br>Le calcul du montant de l'indemnité de privation de jouissance tient compte de l'utilisation habituelle antérieure du terrain.</p>''',
'''Réécriture à droit constant : les deux modes de fixation sont formulés successivement et le critère de calcul est exprimé dans une phrase directe, au même emplacement. Aucune réforme de fond.''',
'''Renvoi au deuxième alinéa de L. 105-1 vérifié dans le corpus : fixation par le tribunal administratif à défaut d'accord amiable, avec prise en compte de la plus-value prévue par cet alinéa. Ce renvoi reste intégral, sans lui substituer un régime d'expropriation. Critère de l'utilisation habituelle antérieure conservé dans le second alinéa substantiel.''')

add('L121-37',
'''<p>Les dommages causés ou subis par les bénéficiaires des servitudes définies aux articles L. 121-31 et L. 121-34 ne peuvent engager la responsabilité civile des propriétaires des terrains, voies et chemins grevés par ces servitudes.</p>''',
'''Réécriture à droit constant : les dommages auxquels s'applique l'exclusion de responsabilité sont placés en sujet. Le champ personnel et matériel de l'exclusion reste identique ; aucune réforme de fond.''',
'''Les dommages causés par les bénéficiaires et ceux qu'ils subissent sont tous deux conservés. L'exclusion demeure celle de la responsabilité civile des propriétaires des terrains, voies et chemins grevés, avec les deux renvois d'origine.''')

add('L121-38',
'''<p>Les dispositions des sections 1 et 2 du présent chapitre s'appliquent, en Guadeloupe, en Guyane, en Martinique et à La Réunion, aux communes littorales définies à l'article L. 321-2 du code de l'environnement et, à Mayotte, à l'ensemble des communes. Cette application exclut les articles L. 121-12, L. 121-13, L. 121-16, L. 121-17 et L. 121-19 et s'effectue sous réserve des dispositions ci-après.</p>''',
'''Réécriture à droit constant : le champ territorial est énoncé avant les exclusions et la réserve des règles spéciales, dans le même alinéa. Aucune réforme de fond.''',
'''Les quatre territoires soumis à la définition des communes littorales sont distingués de Mayotte, où toutes les communes sont visées. Les sections 1 et 2 et les cinq articles exclus sont conservés. Les mesures de densification de policy.json ne suppriment ni ces exclusions ni les règles spéciales qui suivent.''')

add('L121-39',
'''<p>Par dérogation à l'article L. 121-8, l'autorité administrative compétente de l'État peut autoriser, en dehors des espaces proches du rivage et après avis de la commission départementale de la nature, des paysages et des sites, l'implantation d'ouvrages nécessaires à la production d'électricité à partir de l'énergie mécanique du vent et incompatibles avec le voisinage des zones habitées.<br>Elle refuse cette autorisation si les constructions ou installations sont de nature à porter atteinte à l'environnement ou aux sites et paysages remarquables, ou si elles sont incompatibles avec l'exercice d'une activité agricole, pastorale ou forestière.</p>''',
'''Réécriture à droit constant : l'autorité qui autorise et celle qui doit refuser sont explicitement désignées, sans déplacer les deux alinéas substantiels. Aucune réforme de fond.''',
'''Dérogation à L. 121-8, exclusion des espaces proches du rivage, incompatibilité avec le voisinage habité et avis de la commission conservés. Les motifs alternatifs de refus environnementaux, paysagers, agricoles, pastoraux et forestiers sont maintenus. Ce régime éolien n'est pas étendu par les orientations de logement.''')

add('L121-39-1',
'''<p>En Guyane, à Mayotte, à La Réunion, en Martinique et en Guadeloupe, par dérogation à l'article L. 121-8, peuvent être autorisées les constructions ou installations liées aux activités de stockage, de traitement ou de valorisation des déchets et celles nécessaires à la production d'eau potable et à l'assainissement des eaux usées qui sont incompatibles avec le voisinage des zones habitées. Peuvent également être autorisées les installations de production d'électricité à partir d'énergies renouvelables ou d'énergie solaire thermique, les installations de stockage d'énergie couplées aux fins d'alimentation électrique avec ces installations de production d'électricité, ainsi que les constructions et installations nécessaires aux stations de transfert d'énergie par pompage, y compris les ouvrages de raccordement aux réseaux publics d'électricité. Ces autorisations nécessitent l'accord de l'autorité administrative compétente de l'État, après avis de la commission départementale de la nature, des paysages et des sites. Cette autorité refuse son accord si les constructions ou installations concernées sont de nature à porter atteinte à l'environnement. Le changement de destination de ces constructions ou installations n'est autorisé que vers les destinations et les sous-destinations susmentionnées incompatibles avec le voisinage des zones habitées, dans les conditions prévues au présent article.</p>
<p>Seules les stations de transfert d'énergie par pompage dont les caractéristiques répondent aux objectifs de la programmation pluriannuelle de l'énergie du territoire d'implantation du projet, prévue à l'article L. 141-5 du code de l'énergie, sont visées au premier alinéa du présent article.</p>
<p>La dérogation prévue au premier alinéa du présent article s'applique en dehors des espaces proches du rivage et, sauf à Mayotte, au-delà d'une bande de trois kilomètres à compter de la limite haute du rivage ou des plus hautes eaux pour les plans d'eau intérieurs mentionnés à l'article L. 321-2 du code de l'environnement.</p>
<p>Le troisième alinéa du présent article ne s'applique pas aux dérogations concernant les constructions et les installations nécessaires aux stations de transfert d'énergie par pompage mentionnées au premier alinéa.</p>''',
'''Réécriture à droit constant : le premier alinéa est divisé en phrases distinguant les catégories de projets, l'accord requis, le refus obligatoire et le changement de destination. Les quatre alinéas et les renvois internes sont maintenus. Aucune réforme de fond ni nouvelle date d'entrée en vigueur.''',
'''La note historique vise le I de l'article 21 de la loi n° 2026-554 du 29 juin 2026 : entrée en vigueur à une date fixée par décret, au plus tard le 1er septembre 2026. Elle ne fixe aucune date pour le présent projet de réécriture ; la date éventuelle du décret n'est pas fournie. Les cinq territoires, le couplage pour l'alimentation électrique, les raccordements, la programmation énergétique, les trois kilomètres, l'exception de Mayotte et l'exclusion de tout le troisième alinéa pour les stations de pompage sont conservés. Point de cohérence préexistant à contrôler : la source mentionne la production d'électricité à partir d'« énergie solaire thermique » ; cette qualification est maintenue sans la remplacer par une autre filière. La restriction du changement de destination aux destinations et sous-destinations incompatibles avec le voisinage habité est également maintenue.''')

add('L121-40',
'''<p>Dans les espaces proches du rivage, les opérations suivantes sont autorisées :<br>1° L'extension de l'urbanisation dans les secteurs où existe déjà une urbanisation diffuse ;<br>2° Les opérations d'aménagement déjà prévues dans le schéma d'aménagement régional mentionné à l'article L. 4433-7 du code général des collectivités territoriales, au sein de son chapitre particulier valant schéma de mise en valeur de la mer.</p>
<p>Ces dispositions sont entrées en vigueur le 1er mars 2020. Elles ne s'appliquent pas aux procédures d'élaboration ou de révision de schémas d'aménagement régional en cours à cette date.</p>''',
'''Réécriture à droit constant : l'introduction annonce les deux catégories d'opérations autorisées et le 2° situe d'abord le schéma régional, puis son chapitre particulier, en conservant la prévision préalable des opérations. Les subdivisions restent en place. La réserve transitoire figurant dans la note source est explicitée à la suite du dispositif pour préserver les procédures anciennes ; aucune réforme de fond.''',
'''La règle transitoire provient de l'article 7 de l'ordonnance n° 2019-1170 du 13 novembre 2019, cité dans la note source. Le 1er mars 2020 est une date historique et non une date de réforme future. Son insertion après le 2° ne déplace aucune subdivision existante. Les procédures d'élaboration comme celles de révision en cours à cette date demeurent exclues de cette rédaction ; leur régime antérieur n'est pas remplacé. Renvoi au chapitre particulier du schéma d'aménagement régional et à L. 4433-7 conservé.''')

add('L121-41',
'''<p>En l'absence d'un schéma régional approuvé, l'urbanisation peut être réalisée à titre exceptionnel avec l'accord de l'autorité administrative compétente de l'État. Cet accord intervient après avis de la région sur la compatibilité de l'urbanisation envisagée avec les orientations du schéma d'aménagement régional et après avis de la commission départementale de la nature, des paysages et des sites sur l'impact de cette urbanisation sur la nature. Un décret en Conseil d'État détermine les critères selon lesquels l'autorité administrative donne son accord.<br>Le plan local d'urbanisme doit respecter les dispositions de cet accord.</p>''',
'''Réécriture à droit constant : l'exception, les deux avis préalables et l'habilitation réglementaire sont présentés dans des phrases distinctes au même alinéa. L'obligation du plan local d'urbanisme reste dans l'alinéa suivant. Aucune réforme de fond.''',
'''Caractère exceptionnel, accord de l'État, objets distincts des avis de la région et de la commission, décret en Conseil d'État et respect de l'accord par le plan local d'urbanisme conservés. Ambiguïté préexistante à contrôler : en l'absence de schéma régional approuvé, le texte exige un avis au regard des orientations du schéma d'aménagement régional sans préciser le statut de ce schéma ; aucune précision nouvelle n'est inventée.''')

add('L121-42',
'''<p>Entre les zones urbanisables, des espaces naturels ouverts sur le rivage doivent être ménagés pour constituer des coupures d'urbanisation.</p>''',
'''Réécriture à droit constant : l'emplacement des espaces naturels et l'obligation de ménager des coupures d'urbanisation sont formulés directement. Aucune réforme de fond.''',
'''Le caractère naturel des espaces, leur ouverture sur le rivage et leur fonction de coupure entre les zones urbanisables sont conservés. Les orientations de densification ne suppriment pas cette protection.''')

add('L121-43',
'''<p>Sur les pentes proches du littoral, aucune construction ni aucun aménagement ne peut être implanté si cette implantation porte atteinte au caractère paysager des mornes.</p>''',
'''Réécriture à droit constant : l'interdiction est formulée directement et son critère paysager reste explicite. Aucune réforme de fond.''',
'''L'interdiction reste limitée aux constructions et aménagements dont l'implantation, sur les pentes proches du littoral, porte atteinte au caractère paysager des mornes. Aucune dérogation de densification n'est ajoutée.''')

add('L121-44',
'''<p>À Mayotte, aucune construction ni aucun aménagement ne peut être implanté sur le littoral si cette implantation porte atteinte aux plages de sable, aux mangroves, aux lagons ou aux récifs coralliens.</p>''',
'''Réécriture à droit constant : le territoire, les opérations interdites et la condition d'atteinte aux milieux protégés sont exprimés directement. Aucune réforme de fond.''',
'''Les quatre milieux protégés et le champ limité au littoral de Mayotte sont conservés. L'interdiction demeure conditionnée à l'atteinte résultant de l'implantation.''')

add('L121-45',
'''<p>La bande littorale s'étend du rivage de la mer à la limite supérieure de la réserve domaniale dite des cinquante pas géométriques, définie à l'article L. 5111-2 du code général de la propriété des personnes publiques et, à Mayotte, à l'article L. 5331-4 de ce code.<br>Lorsque cette réserve n'est pas délimitée ou n'a pas été instituée, la bande a une largeur de 81,20 mètres à compter de la limite haute du rivage.</p>
<p>Dans les communes mentionnées à l'article L. 121-22-1, le plan local d'urbanisme ou le document en tenant lieu élargit la bande littorale lorsque la projection du recul du trait de côte à l'horizon de trente ans le justifie. Il porte alors sa largeur au-delà de la limite supérieure de la réserve domaniale, lorsque celle-ci a été instituée, et, à défaut de délimitation, à plus de 81,20 mètres à compter de la limite haute du rivage. Cette bande correspond à la zone définie au 1° de l'article L. 121-22-2.</p>''',
'''Réécriture à droit constant : la délimitation de principe, la largeur supplétive et l'élargissement lié au recul du trait de côte sont exprimés plus directement. Les deux alinéas du premier paragraphe et le paragraphe relatif au recul sont conservés ; aucune réforme de fond.''',
'''Les deux occurrences de 81,20 mètres, l'horizon de trente ans, le 1° de L. 121-22-2 et les renvois domaniaux, dont celui propre à Mayotte, sont conservés. L. 121-22-1 et L. 121-22-2 ont été vérifiés dans le corpus. Point de rédaction préexistant : le seuil supplétif vise l'absence de délimitation ou d'institution de la réserve, tandis que la phrase relative à l'élargissement ne répète que l'absence de délimitation. Cette différence est maintenue sans correction implicite.''')

add('L121-46',
'''<p>En dehors des espaces urbanisés, les terrains situés dans la bande littorale définie à l'article L. 121-45 sont réservés aux installations nécessaires à des services publics, à des activités économiques ou à des équipements collectifs, à condition que ces services, activités ou équipements soient liés à l'usage de la mer. Ces installations doivent organiser ou préserver l'accès et la libre circulation le long du rivage.</p>''',
'''Réécriture à droit constant : le lien exigé avec l'usage de la mer est rattaché explicitement aux services, activités et équipements concernés. L'obligation relative au passage est exprimée directement ; aucune réforme de fond.''',
'''Champ hors des espaces urbanisés, renvoi à L. 121-45, nécessité des installations et lien maritime conservés. L'accès et la libre circulation le long du rivage demeurent tous deux couverts par l'obligation d'organiser ou de préserver.''')

add('L121-47',
'''<p>Dans les parties urbanisées de la commune comprises dans la bande littorale définie à l'article L. 121-45, les terrains doivent être préservés lorsqu'ils sont utilisés comme plages, espaces boisés, parcs ou jardins publics.<br>Les espaces restés naturels dans les parties urbanisées de cette bande doivent également être préservés, sauf si un intérêt public exposé au plan local d'urbanisme justifie une autre affectation.</p>''',
'''Réécriture à droit constant : les terrains protégés sont énoncés directement et l'obligation de préservation des espaces restés naturels est répétée pour rendre lisible la portée de l'exception. Les deux alinéas substantiels sont conservés ; aucune réforme de fond.''',
'''La réserve d'intérêt public exposé au plan local d'urbanisme reste attachée au seul second alinéa, relatif aux espaces restés naturels. Elle n'est pas étendue aux plages, espaces boisés, parcs et jardins publics du premier alinéa. Renvoi à L. 121-45 conservé.''')

add('L121-48',
'''<p>Sous réserve de la préservation des plages, des espaces boisés, des parcs ou des jardins publics, le plan local d'urbanisme peut délimiter les secteurs de la zone dite des cinquante pas géométriques situés dans les parties urbanisées de la commune ou au droit de ces parties. Ces secteurs doivent être déjà équipés ou occupés à la date du 1er janvier 1997 ou, à Mayotte, à la date du 29 juillet 2005. Les secteurs ainsi délimités peuvent être affectés à des services publics, des équipements collectifs, des opérations de réaménagement de quartier, de logement à caractère social et de résorption de l'habitat insalubre, des commerces, des structures artisanales, des équipements touristiques et hôteliers, ainsi qu'à toute autre activité économique dont la localisation à proximité de la mer est justifiée par son usage ou par une nécessité économique de desserte par voie maritime. Dans ce cas, des mesures compensatoires permettant le maintien de l'équilibre du milieu marin et terrestre doivent être mises en œuvre.<br>Ces installations doivent organiser ou préserver l'accès et la libre circulation le long du rivage.<br>Dans ces secteurs, l'adaptation, le changement de destination, la réfection, la reconstruction et l'extension limitée des constructions existantes sont autorisés.</p>''',
'''Réécriture à droit constant : les conditions de délimitation, les dates d'équipement ou d'occupation et les affectations autorisées sont réparties en phrases dans le premier alinéa. Les mesures compensatoires, le passage et les interventions sur les constructions sont intégralement conservés à leur emplacement. Aucune réforme de fond.''',
'''Les trois alinéas substantiels restent dans le même ordre. Dates du 1er janvier 1997 et du 29 juillet 2005 pour Mayotte, alternative entre équipement et occupation, secteurs au droit des parties urbanisées, liste complète des affectations et justification maritime des seules autres activités économiques conservés. La limitation porte toujours sur l'extension des constructions existantes ; les autres interventions énumérées ne reçoivent pas cette restriction nouvelle. Maintien des mesures compensatoires marines et terrestres et de l'accès et de la circulation le long du rivage.''')

add('L121-49',
'''<p>Les secteurs situés dans la bande littorale définie à l'article L. 121-45 et à proximité des parties urbanisées de la commune peuvent recevoir les affectations prévues au présent alinéa s'ils étaient occupés par une urbanisation diffuse à la date du 1er janvier 1997 ou, à Mayotte, à la date du 29 juillet 2005. Ces affectations sont subordonnées à l'identification de ces secteurs dans le chapitre particulier du schéma régional valant schéma de mise en valeur de la mer et à la préservation des plages, des espaces boisés, des parcs et des jardins publics. Elles peuvent concerner des services publics, des équipements collectifs, des programmes de logements à caractère social, des commerces, des structures artisanales et des équipements touristiques et hôteliers. Dans ce cas, des mesures compensatoires permettant le maintien de l'équilibre du milieu marin et terrestre doivent être mises en œuvre.<br>Ces installations doivent organiser ou préserver l'accès et la libre circulation le long du rivage.<br>Dans ces secteurs, l'adaptation, le changement de destination, la réfection, la reconstruction et l'extension limitée des constructions existantes sont autorisés.</p>''',
'''Réécriture à droit constant : les conditions territoriales, temporelles et de planification sont distinguées de la liste des affectations dans le premier alinéa. Les deux alinéas suivants gardent leurs objets et positions. Aucune réforme de fond.''',
'''Dates du 1er janvier 1997 et du 29 juillet 2005, urbanisation diffuse, proximité des parties urbanisées et renvoi à L. 121-45 conservés. Les affectations restent celles énumérées par cet article, sans ajout des autres activités économiques admises au régime distinct de L. 121-48. Identification au chapitre particulier du schéma, préservation des espaces, compensation marine et terrestre, passage et cinq interventions sur les constructions existantes sont conservés ; seule l'extension est qualifiée de limitée.''')

add('L121-50',
'''<p>La liste des espaces et milieux à préserver fixée par le décret prévu à l'article L. 121-23 comprend également les récifs coralliens, les lagons et les mangroves, en fonction de leur intérêt écologique.</p>''',
'''Réécriture à droit constant : le texte précise que l'ajout porte sur la liste fixée par le décret, ce qui explicite l'objet du renvoi. Les trois milieux et le critère écologique restent identiques ; aucune réforme de fond.''',
'''Renvoi vérifié dans le corpus : L. 121-23 prévoit bien un décret fixant la liste des espaces et milieux à préserver. Les récifs coralliens, lagons et mangroves restent pris en compte selon leur intérêt écologique, dans le champ territorial de la section.''')

add('L121-51',
'''<p>En Guadeloupe, en Guyane, en Martinique, à La Réunion et à Mayotte, la servitude transversale peut être instituée non seulement sur les voies et chemins privés d'usage collectif existants, mais aussi sur les propriétés limitrophes du domaine public maritime. Elle est alors établie par la création d'un chemin situé à au moins cinq cents mètres de toute voie publique d'accès transversale au rivage. L'emprise de cette servitude ne peut dépasser trois mètres de largeur. La servitude doit être distante d'au moins dix mètres des bâtiments à usage d'habitation édifiés avant le 1er août 2010. Toutefois, pour les terrains situés dans la zone comprise entre la limite du rivage de la mer et la limite supérieure de la zone dite des cinquante pas géométriques, définie à l'article L. 5111-2 du code général de la propriété des personnes publiques et, à Mayotte, à l'article L. 5331-4 de ce code, cette distance de dix mètres ne s'applique que si les terrains ont été acquis de l'État avant le 1er août 2010 ou en vertu d'une demande déposée avant cette date.</p>''',
'''Réécriture à droit constant : le support supplémentaire de la servitude est distingué des conditions de création du chemin, puis les limites d'emprise et de distance sont énoncées dans des phrases séparées. L'exception applicable dans la zone des cinquante pas géométriques reste dans le même alinéa. Aucune réforme de fond.''',
'''Les cinq territoires, cinq cents mètres au minimum de toute voie publique d'accès transversale, trois mètres de largeur au maximum, dix mètres au minimum et les deux références au 1er août 2010 sont conservés. Dans la zone des cinquante pas, la condition d'acquisition auprès de l'État avant cette date ou sur demande déposée avant elle porte exclusivement sur l'application de la distance de dix mètres ; elle ne devient pas une condition générale d'institution de la servitude. Les deux renvois domaniaux sont maintenus. Articulation avec L. 121-34 conservée.''')

add('L122-1',
'''<p>Le présent chapitre fixe les conditions d'utilisation et de protection de l'espace montagnard. Il s'applique dans les zones de montagne définies à l'article 3 de la loi n° 85-30 du 9 janvier 1985 relative au développement et à la protection de la montagne.</p>''',
'''Réécriture à droit constant : l'objet du chapitre et son champ territorial sont présentés dans deux phrases. Aucune réforme de fond.''',
'''Le champ demeure celui des zones définies à l'article 3 de la loi n° 85-30 du 9 janvier 1985, dont le numéro, la date et l'intitulé sont conservés. La réforme de densification n'élargit ni ne réduit ce champ.''')

add('L122-1-1',
'''<p>Dans les communes soumises à la fois au chapitre Ier du présent titre et au présent chapitre, et riveraines d'un plan d'eau intérieur d'une superficie supérieure à 1 000 hectares au sens du 1° de l'article L. 321-2 du code de l'environnement, le schéma de cohérence territoriale peut, par dérogation à l'article L. 121-1, déterminer les secteurs auxquels le chapitre Ier du présent titre ne s'applique pas. Il détermine ces secteurs en fonction des spécificités locales et en dehors de la bande littorale de cent mètres définie à l'article L. 121-16 du présent code.</p>''',
'''Réécriture à droit constant : les conditions cumulatives tenant aux communes et au plan d'eau sont énoncées avant la faculté du schéma de cohérence territoriale. Les critères de détermination des secteurs sont explicités dans une seconde phrase au même alinéa. Aucune réforme de fond.''',
'''Le seuil reste strictement supérieur à 1 000 hectares ; la bande de cent mètres ne peut être incluse dans les secteurs soustraits au chapitre Ier. L'exclusion facultative ne concerne que le chapitre Ier et ne supprime pas l'application du chapitre de montagne. Les renvois à L. 121-1 et L. 121-16 ont été vérifiés dans le corpus ; le 1° de L. 321-2 du code de l'environnement est maintenu, de même que l'exigence des spécificités locales.''')

assert len(sources) == len(drafts) == 24
answer = []
for source in sources:
    answer.append({**{key: source[key] for key in ('code_id','source_id','source_sha256','number')}, **drafts[source['number']]})
Path('answer.json').write_text(json.dumps(answer, ensure_ascii=False, indent=2) + '\n')
print(f'answer.json : {len(answer)} articles, {sum(len(a["proposed_xml"]) for a in answer)} caractères de texte XML proposé.')
